// storeActions returns the actions of the generated sequences of Store
// over the subject that subject returns. The actions of a case take their
// keys from the pools that it draws.
func storeActions(c *prop.Case, subject func() deadcheck.Store) []stateful.Action[struct{}] {
	keysString := c.Draw(prop.List(prop.Of[string](), prop.Unique(), prop.MinSize(1), prop.MaxSize(3)), "keys.string")
	return []stateful.Action[struct{}]{
		{
			Name: "Get",
			Input: func(c *prop.Case, _ struct{}) any {
				key := c.Draw(prop.SampledFrom(keysString...), "get.key")
				return []any{key}
			},
			Run: func(c *prop.Case, client int, input any) {
				args, _ := input.([]any)
				call := c.History().Invoke(client, "Get", args, args[0])
				values, err := storeGetCall(c.Context(), subject(), args)
				conform.Complete(c.Context(), call, err, values...)
			},
		},
		{
			Name: "Put",
			Input: func(c *prop.Case, _ struct{}) any {
				key := c.Draw(prop.SampledFrom(keysString...), "put.key")
				value := c.Draw(prop.Of[string](), "put.value")
				return []any{key, value}
			},
			Run: func(c *prop.Case, client int, input any) {
				args, _ := input.([]any)
				call := c.History().Invoke(client, "Put", args, args[0])
				values, err := storePutCall(c.Context(), subject(), args)
				conform.Complete(c.Context(), call, err, values...)
			},
		},
		{
			Name: "Close",
			Run: func(c *prop.Case, client int, input any) {
				args, _ := input.([]any)
				call := c.History().Invoke(client, "Close", args)
				values, err := storeCloseCall(c.Context(), subject(), args)
				conform.Complete(c.Context(), call, err, values...)
			},
		},
	}
}

// storeGetCall calls Get on subject with the arguments args, and returns
// the values of the call beside its error.
func storeGetCall(ctx context.Context, subject deadcheck.Store, args []any) ([]any, error) {
	a0, _ := args[0].(string)
	r0, err := subject.Get(ctx, a0)
	return []any{r0}, err
}

// storePutCall calls Put on subject with the arguments args, and returns
// the values of the call beside its error.
func storePutCall(ctx context.Context, subject deadcheck.Store, args []any) ([]any, error) {
	a0, _ := args[0].(string)
	a1, _ := args[1].(string)
	return nil, subject.Put(ctx, a0, a1)
}

// storeCloseCall calls Close on subject with the arguments args, and
// returns the values of the call beside its error.
func storeCloseCall(ctx context.Context, subject deadcheck.Store, args []any) ([]any, error) {
	return nil, subject.Close()
}

